// src/services/db/index.ts
var cachedUmamiClient = null;
var cachedUmamiKey = "";
function resolveDatabaseType(env) {
  if (!env) return null;
  const explicitType = (env.DATABASE_TYPE || env.DB_TYPE || env.STATS_PROVIDER || "").toLowerCase().trim();
  if (explicitType === "none" || explicitType === "off" || explicitType === "disabled") {
    return null;
  }
  const hasUmami = Boolean(env.UMAMI_WEBSITE_ID || env.UMAMI_ID);
  if (hasUmami) {
    return "umami";
  }
  return null;
}
function isStatsEnabled(env) {
  if (!env) return false;
  const enableVar = env.ENABLE_STATS;
  if (enableVar === "false" || enableVar === false) return false;
  const disableVar = env.DISABLE_STATS;
  if (disableVar === "true" || disableVar === true) return false;
  return resolveDatabaseType(env) !== null;
}
function getDbClient(target) {
  if (!target) return null;
  const env = target;
  const type = resolveDatabaseType(env);
  if (type === "umami") {
    const host = (env.UMAMI_HOST || env.UMAMI_URL || env.UMAMI_ENDPOINT || "https://cloud.umami.is").trim();
    const websiteId = (env.UMAMI_WEBSITE_ID || env.UMAMI_ID || "").trim();
    const apiKey = (env.UMAMI_API_KEY || env.UMAMI_TOKEN || "").trim();
    const enableScript = env.ENABLE_UMAMI_SCRIPT !== "false" && env.ENABLE_UMAMI_SCRIPT !== false;
    if (!websiteId) return null;
    const cacheToken = `${host}:${websiteId}:${apiKey}:${enableScript}`;
    if (!cachedUmamiClient || cachedUmamiKey !== cacheToken) {
      cachedUmamiKey = cacheToken;
      const storage = getBlogStorage(env);
      cachedUmamiClient = new UmamiDatabaseClient({
        host,
        websiteId,
        apiKey,
        storage,
        enableScript
      });
    }
    return cachedUmamiClient;
  }
  return null;
}

// src/services/stats.ts
async function recordPageView(target, input2) {
  if (!isStatsEnabled(target)) {
    return { views: 0, uv: 0 };
  }
  const client = getDbClient(target);
  if (!client) {
    return { views: 0, uv: 0 };
  }
  return client.recordPageView(input2);
}
async function getTopPosts(target, limit = 3) {
  if (!isStatsEnabled(target)) return [];
  const client = getDbClient(target);
  if (!client) return [];
  return client.getTopPosts(limit);
}
async function getPostStats(target, slug) {
  if (!isStatsEnabled(target)) return { views: 0, uv: 0 };
  const client = getDbClient(target);
  if (!client) return { views: 0, uv: 0 };
  return client.getPostStats(slug);
}
async function getAllPostStats(target) {
  if (!isStatsEnabled(target)) return {};
  const client = getDbClient(target);
  if (!client) return {};
  return client.getAllPostStats();
}

// src/routes/stats.ts
var stats = new Hono2();
var BOT_UA_REGEX = /(bot|spider|crawl|slurp|googlebot|bingbot|yandex|baidu|duckduck|facebookexternalhit|whatsapp|twitterbot|slackbot|applebot)/i;
stats.post("/view", async (c) => {
  if (!isStatsEnabled(c.env)) {
    return c.json({ success: true, enabled: false, message: "Stats feature is disabled" });
  }
  const userAgent = c.req.header("user-agent") || "";
  if (BOT_UA_REGEX.test(userAgent)) {
    return c.json({ success: true, message: "Ignored bot" });
  }
  try {
    const body = await c.req.json().catch(() => ({}));
    const slug = (body.slug || "").trim();
    if (!slug) {
      return c.json({ success: false, message: "Missing slug" }, 400);
    }
    const rawIp = c.req.header("cf-connecting-ip") || c.req.header("x-real-ip") || c.req.header("x-client-ip") || c.req.header("x-forwarded-for")?.split(",")[0] || "127.0.0.1";
    const ip = rawIp.trim();
    const country = c.req.header("cf-ipcountry") || c.req.header("x-vercel-ip-country") || c.req.header("x-country") || "";
    const result = await recordPageView(c.env, {
      slug,
      url: body.url || "",
      referrer: body.referrer || "",
      userAgent,
      ip,
      country,
      sessionId: body.sessionId || "",
      clientTracked: Boolean(body.clientTracked),
      language: body.language || "",
      screen: body.screen || ""
    });
    return c.json({
      success: true,
      data: result
    });
  } catch (err) {
    return c.json({ success: false, message: err.message }, 500);
  }
});
stats.get("/all", async (c) => {
  if (!isStatsEnabled(c.env)) {
    return c.json({ success: true, enabled: false, data: {} });
  }
  try {
    const data = await getAllPostStats(c.env);
    c.header("Cache-Control", "public, max-age=60, s-maxage=300, stale-while-revalidate=600");
    return c.json({ success: true, enabled: true, data });
  } catch (err) {
    return c.json({ success: false, enabled: true, data: {}, message: err.message }, 500);
  }
});
stats.get("/top", async (c) => {
  if (!isStatsEnabled(c.env)) {
    return c.json({ success: true, enabled: false, data: [] });
  }
  const limit = Math.min(20, Math.max(1, parseInt(c.req.query("limit") || "3", 10)));
  const data = await getTopPosts(c.env, limit);
  return c.json({ success: true, enabled: true, data });
});
stats.get("/post", async (c) => {
  if (!isStatsEnabled(c.env)) {
    return c.json({ success: true, enabled: false, data: { views: 0, uv: 0 } });
  }
  const slug = c.req.query("slug") || "";
  if (!slug) {
    return c.json({ success: false, message: "Missing slug" }, 400);
  }
  try {
    const data = await getPostStats(c.env, slug);
    c.header("Cache-Control", "public, max-age=60, s-maxage=300, stale-while-revalidate=600");
    return c.json({ success: true, enabled: true, data });
  } catch (err) {
    return c.json({ success: false, enabled: true, data: { views: 0, uv: 0 }, message: err.message }, 500);
  }
});
stats.get("/status", (c) => {
  const type = resolveDatabaseType(c.env);
  const enabled = isStatsEnabled(c.env);
  return c.json({
    success: true,
    data: {
      provider: type || "none",
      database: type || "none",
      configured: Boolean(type),
      enabled,
      ...type === "umami" ? {
        umamiHost: c.env.UMAMI_HOST || c.env.UMAMI_URL || "https://cloud.umami.is",
        websiteId: c.env.UMAMI_WEBSITE_ID || c.env.UMAMI_ID || "",
        hasApiKey: Boolean(c.env.UMAMI_API_KEY || c.env.UMAMI_TOKEN),
        scriptEnabled: c.env.ENABLE_UMAMI_SCRIPT !== "false" && c.env.ENABLE_UMAMI_SCRIPT !== false
      } : {}
    }
  });
});
var stats_default = stats;

